input.newString:
/* 5. 긴 오류·쿼터 안내 overflow 예외 — 재지시22: flex-shrink:0 으로 안내가 최대높이
 * 안에서 읽힐 공간을 보장한다. 한 줄 띠로 강제 축소·잘라 숨기기 금지.
 * 내용이 최대높이를 넘으면 해당 안내 내부 스크롤(확인 버튼 포함)로 접근한다. */
.saved-routes > .saved-routes__error,
.saved-routes > .saved-routes__quota-notice {
  flex-shrink: 0;
  min-height: 0;
  overflow-y: auto;
  max-height: 9rem;
  max-height: 30vh;
  max-height: 30dvh;
}

/* 재지시22 예외 상태: 긴 오류·쿼터 안내가 있을 때만 본문 스크롤을 허용한다.
 * 일반 상태(안내 없음·짧음)는 본문 고정·목록만 스크롤 그대로.
 * 300px대 화면에 긴 안내+목록을 동시에 다 담을 수 없으므로 예외 본문 스크롤로
 * 접근시키고 창 헤더(.oc-modal__head, 본문 밖)는 고정 유지. 가로 overflow는 0. */
.oc-modal__body:has(.saved-routes > .saved-routes__error),
.oc-modal__body:has(.saved-routes > .saved-routes__quota-notice) {
  overflow-x: hidden;
  overflow-y: auto;
}

/* 예외 본문 안 saved-routes는 자연 높이(flex 고정 해제) — overflow 잘림 없음. */
.oc-modal__body:has(.saved-routes > .saved-routes__error) .saved-routes,
.oc-modal__body:has(.saved-routes > .saved-routes__quota-notice) .saved-routes {
  flex: 0 0 auto;
}

/* 예외 목록은 내부 스크롤을 유지하되 최대 40vh/dvh로 묶고,
 * 최소 88px(rename 입력+저장/취소 1묶음이 보이는 공간)를 확보한다. */
.oc-modal__body:has(.saved-routes > .saved-routes__error) .saved-routes > .saved-routes__list,
.oc-modal__body:has(.saved-routes > .saved-routes__quota-notice) .saved-routes > .saved-routes__list {
  flex: 0 0 auto;
  max-height: 40vh;
  max-height: 40dvh;
  min-height: 88px;
}

